T[236]={"^Melee haste and damage increased by (.-)%%, stacking (.-) times%.%s*$","A aceleração e o dano corpo a corpo aumentam em {{1}}%, acumulando até {{2}} vezes."}
T[412]={"^Drains (.-) health every (.-) sec to the caster, or causes healing to an ally%.%s*$","Drena {{1}} vida a cada {{2}} s o conjurador, ou causa cura a um aliado."}
T[413]={"^Causes (.-) Shadow damage to attackers%.%s*$","Causa {{1}} de dano de Sombra aos atacantes."}
T[618]={"^Removes the Cooldown of your Dark Liturgy spell%.%s*$","Elimina a recarga de seu feitiço Liturgia sombria."}
T[620]={"^Reduces the chance that |cffffffffVestigial Muck|r is broken by damage by (.-)%%%.%s*$","Reduz a chance de que |cffffffffLodo Vestigial|r se quebre devido a dano em {{1}}%."}
T[622]={"^Increases your healing received by (.-)%% and the damage and healing of |cffffffffSanguine Rupture|r by (.-)%%%.%s*$","Aumenta sua cura recebida em {{1}}% e o dano e a cura de |cffffffffRuptura Sanguínea|r em {{2}}%."}
T[623]={"^Bloodmoon Blast, Consume and Taldaram's Torment now have a (.-)%% chance to apply |cffffffffGrimclaw|r when they deal damage%.%s*$","Explosão da Lua de Sangue, Consumir e Tormento de Taldaram agora têm {{1}}% de chance de aplicar |cffffffffGarra Sinistra|r ao causarem dano."}
T[627]={"^|cffffffffNight Hunter's Howl|r applies |cffffffffWorgen Bite|r to all enemies struck%.%s*$","|cffffffffUivo do Caçador Noturno|r aplica |cffffffffMordida de Worgen|r a todos os inimigos atingidos."}
T[638]={"^Increases the healing done by |cffffffffLifedrinker|r by (.-)%%%.%s*$","Aumenta a cura realizada por |cffffffffBebedor de Vida|r em {{1}}%."}
T[1278]={"^Cannot be Interrupted or Silenced%.\n\nRegenerating (.-)%% of  Missing Rage and (.-)%% Maximum Health every (.-) seconds%.%s*$","não pode ser interrompido nem silenciado.\n\nRegenerando {{1}}% de Ameaça de Fúria perdida e {{2}}% de Vida máxima a cada {{3}} segundos."}
T[1416]={"^A Bloodmage's Shadow Colony is watching over you, triggering Call of the Darkwing upon taking damage%.%s*$","Uma Colônia Sombria do Mago Sangrento vigia você e ativa Chamado da Asa Negra quando você recebe dano."}
T[1544]={"^Healing for (.-)%% of all damage dealt%.%s*$","Cura pel{{1}}% de todo dano causado."}
T[1545]={"^|cffffffffClaw Sweep|r now spreads |cffffffffInfected Claw|r from affected targets to another random enemy within (.-)yd%.%s*$","|cffffffffZarpada em varredura|r agora propaga |cffffffffGarra infectada|r a outro inimigo aleatório em um raio de {{1}}m afetado."}
T[1735]={"^Allows you to wield Staves, but reduces your Physical Damage done by (.-)%% at all times%.\n\nIncreases the Healing you gain from your Lifedrinker spell by (.-)%%%.%s*$","Permite empunhar Cajados, mas reduz em {{1}}% o dano Físico causado o tempo todo.\n\nAumenta em {{2}}% a cura que você recebe de |cffffffffBebedor de Vida|r."}
T[1869]={"^Striking nearby enemies%.%s*$","Golpeia aos inimigos próximos."}
T[1894]={"^Immune to all damage%. Pacified and silenced%. Movement speed reduced by (.-)%%%.%s*$","Imune a todo dano. Pacificado e silenciado. A velocidade de movimento é reduzida em {{1}}%."}
T[1905]={"^Allows the Exsanguination effect from your Shadowfang Shield to stack up to (.-) additional times%.%s*$","Permite que o efeito Exsanguinação de Escudo Presa Sombria acumule até {{1}} vezes adicionais."}
T[2030]={"^Charmed%.\nTransformed into Shadowfang Glutton%.%s*$","Encantado.\nTransformado em Glutão Presa Sombria."}
T[2984]={"^Causes (.-) Shadow damage to attackers%.%s*$","Causa {{1}} de dano de Sombra aos atacantes."}
T[3378]={"^Healing for (.-)%% of all damage dealt%. Suffering (.-)%% maximum health damage every sec%.%s*$","Curando em {{1}}% de todo dano causado. Sofre {{2}}% dano máximo de vida a cada segundo."}
T[3668]={"^Your Rage will not drop below 100%.%s*$","Sua raiva não ficará abaixo de 100."}
T[3707]={"^After (.-) you will become a Lesser Worgen for (.-)%.%s*$","Depois de {{1}} te se transformará em um Worgen Menor durante {{2}}."}
T[3708]={"^Bleeding for (.-) Shadow Damage every (.-) sec%.%s*$","Sangra, sofrendo {{1}} de dano de Sombra a cada {{2}} s."}
T[3709]={"^Movement Speed reduced by (.-)%%%.%s*$","A velocidade de movimento reduz em {{1}}%."}
T[3710]={"^(.-) Physical Damage every (.-) seconds%.%s*$","{{1}} dano Físico a cada {{2}} segundos."}
T[3766]={"^Gives direct Shadow Damage and healing effects a (.-)%% chance to cause a |cffffffffBloodsore|r, stacking (.-) times%.\n\n|cffffffffLifedrinker|r ticks consume a stack of |cffffffffBloodsore|r to increase the damage or healing of subsequent ticks by (.-)%%%.%s*$","Seus efeitos de dano direto de Sombra e de cura têm {{1}}% de chance de causar uma |cffffffffFerida Sanguinária|r, acumulando até {{2}} vezes.\n\nCada pulso de |cffffffffBebedor de Vida|r consome um acúmulo de |cffffffffFerida Sanguinária|r para aumentar em {{3}}% o dano ou a cura dos pulsos seguintes."}
