T[14936]={"^Periodic damage ticks now cause enemies to spill a pool of blood beneath them%.\n\nAllies in |cffa966f0Cursed Form|r who move through the pools of blood gain |cffffffffTrail of Blood|r for (.-)%.%s*$","Seus pulsos de dano periódico fazem os inimigos derramarem uma poça de sangue sob eles.\n\nAliados em |cffa966f0Forma Amaldiçoada|r que atravessarem essas poças recebem |cffffffffRastro de Sangue|r durante {{1}}."}
T[14970]={"^REMOVED%s*$","REMOVIDO."}
T[15103]={"^Increases all damage you deal by (.-)%% and threat generated by all abilities is increased by (.-)%% while you are in a Tank Stance%.%s*$","Aumenta seu dano em {{1}}% e aumenta a ameaça gerada por todas suas habilidades em {{2}}% enquanto estiver em uma Postura de Tanque."}
T[15104]={"^Increases all damage you deal by (.-)%% and threat generated by all abilities is increased by (.-)%% while you are in a Tank Stance%.\n\nTank Stance refers to: Righteous Fury, Defensive Stance, Bear form, Mana%-Forged Barrier or Dark Apotheosis%.%s*$","Aumenta em {{1}}% todo o dano que você causa e em {{2}}% a ameaça gerada por todas as suas habilidades enquanto estiver em uma Postura de Tanque.\n\nPostura de Tanque se refere a: Fúria Justiceira, Postura Defensiva, Forma de Urso, Barreira Forjada com Mana ou Apoteose Sombria."}
T[15105]={"^Increases all damage you deal by (.-)%% and threat generated by all abilities is increased by (.-)%% while you are in a Tank Stance%.%s*$","Aumenta seu dano em {{1}}% e aumenta a ameaça gerada por todas suas habilidades em {{2}}% enquanto estiver em uma Postura de Tanque."}
T[15106]={"^Increases all damage you deal by (.-)%% and threat generated by all abilities is increased by (.-)%% while you are in a Tank Stance%.\n\nTank Stance refers to: Righteous Fury, Defensive Stance, Bear form, Mana%-Forged Barrier or Dark Apotheosis%.%s*$","Aumenta em {{1}}% todo o dano que você causa e em {{2}}% a ameaça gerada por todas as suas habilidades enquanto estiver em uma Postura de Tanque.\n\nPostura de Tanque se refere a: Fúria Justiceira, Postura Defensiva, Forma de Urso, Barreira Forjada com Mana ou Apoteose Sombria."}
T[15756]={"^Your effective health is limited to 90%% of your maximum health%.\n\nAbsorbs all healing taken and converts it into a Blood Shield%.\n\nInflicts Shadow damage equal to (.-)%% of maximum health every second%.%s*$","Sua vida efetiva fica limitada a 90% da vida máxima.\n\nAbsorve toda a cura recebida e a converte em um Escudo de Sangue.\n\nCausa dano de Sombra equivalente a {{1}}% da vida máxima a cada segundo."}
T[16057]={"^Your effective health is limited to 90%% of your maximum health%.\n\nAbsorbs all healing taken and converts it into a Blood Shield%.\n\nInflicts Shadow damage equal to (.-)%% of maximum health every second%.%s*$","Sua vida efetiva fica limitada a 90% da vida máxima.\n\nAbsorve toda a cura recebida e a converte em um Escudo de Sangue.\n\nCausa dano de Sombra equivalente a {{1}}% da vida máxima a cada segundo."}
T[17360]={"^\nTeaches you Metamorphosis %(Dark Apotheosis%) and Taunt %(Dark Apotheosis%)%. \n\nYour Metamorphosis ability is transformed into Demon Spikes if you know Metamorphosis%.\n\nThe damage done by you and your pets is reduced by 40%%, and reduces the cooldown of your Immolation aura by 20 seconds%. \n\nWhile dual wielding you gain Dark Apotheosis%.\n\nShadow Cleave now costs 20 rage, and can only hit one target%. After dealing damage with Shadow Cleave your next damaging spell with a cast time will heal your summoned demon and restore 1%% of their maximum mana, and extend your Immolation Aura by 3 seconds%. This effect can only occur once every second%.%s*$","\nEnsina |cffffffffMetamorfose (Apoteose Sombria)|r e |cffffffffProvocar (Apoteose Sombria)|r.\n\nSe você conhecer Metamorfose, ela é transformada em |cffffffffEspinhos Demoníacos|r.\n\nO dano causado por você e seus mascotes é reduzido em 40%, e a recarga de |cffffffffAura de Imolação|r é reduzida em 20 s.\n\nEnquanto empunha duas armas, você recebe |cffffffffApoteose Sombria|r.\n\n|cffffffffCutilada Sombria|r passa a custar 20 de Raiva e só pode atingir um alvo. Após causar dano com Cutilada Sombria, seu próximo feitiço de dano com tempo de lançamento cura o demônio evocado, restaura 1% da mana máxima dele e prolonga |cffffffffAura de Imolação|r em 3 s. Este efeito só pode ocorrer uma vez por segundo."}
T[17368]={"^You are no longer in Dark Apotheosis but your damage still hasn't returned to normal%.%s*$","Não está na Apoteose Sombria, mas seu dano ainda não voltou à normalidade."}
T[17375]={"^Deals (.-) Shadow damage every 2 seconds%.%s*$","Causa {{1}} de dano de Sombra a cada 2 segundos."}
T[17381]={"^Missile Barrage warlock dot SLS%s*$","Barragem de Mísseis feitiço SLS"}
T[17535]={"^Increases the damage of your combo point generating Rogue abilities by (.-)%% and Dark Intent by additional (.-)%%%.%s*$","Aumenta o dano de suas habilidades de geração de pontos de combo em {{1}}% e Intenção Negra em mais {{2}}%."}
T[17825]={"^Releases a wave of Shadow Bolts%s*$","Liberar uma onda de Setas Sombrias."}
T[18524]={"^Your Rage will not drop below 100%.%s*$","Sua raiva não ficará abaixo de 100."}
T[19017]={"^When the Accursed Blood Mage runs over this, they gain a stack of |cffffffffDarkcasting|r for 30 sec, stacking 10 times%.%s*$","Quando o Mago de Sangue Maldito passa por isto, obtém um acúmulo de |cffffffffEmitir Escuridão|r durante 30 s, até um máximo de 10 acúmulos."}
T[19154]={"^If this reaches 3 stacks, the stacks are consumed and the Bloodmage unleashes a massive bite attack upon you%.%s*$","Se esta acúmulo alcança 3 capas, as capas são consumidas e o Sanguemago te ataca com um mordedura massiva."}
T[19175]={"^(.-) Shadow Damage every 3 seconds%.%s*$","{{1}} dano de Sombra a cada 3 segundos."}
T[20264]={"^\nTeaches you Metamorphosis %(Dark Apotheosis%) and Taunt %(Dark Apotheosis%)%. \n\nYour Metamorphosis ability is transformed into Demon Spikes if you know Metamorphosis%.\n\nThe damage done by you and your pets is reduced by 40%%, and reduces the cooldown of your Immolation aura by 20 seconds%. \n\nWhile dual wielding you gain Dark Apotheosis%.\n\nShadow Cleave now costs 20 rage, and can only hit one target%. After dealing damage with Shadow Cleave your next damaging spell with a cast time will heal your summoned demon and restore 1%% of their maximum mana, and extend your Immolation Aura by 3 seconds%. This effect can only occur once every second%.%s*$","\nEnsina |cffffffffMetamorfose (Apoteose Sombria)|r e |cffffffffProvocar (Apoteose Sombria)|r.\n\nSe você conhecer Metamorfose, ela é transformada em |cffffffffEspinhos Demoníacos|r.\n\nO dano causado por você e seus mascotes é reduzido em 40%, e a recarga de |cffffffffAura de Imolação|r é reduzida em 20 s.\n\nEnquanto empunha duas armas, você recebe |cffffffffApoteose Sombria|r.\n\n|cffffffffCutilada Sombria|r passa a custar 20 de Raiva e só pode atingir um alvo. Após causar dano com Cutilada Sombria, seu próximo feitiço de dano com tempo de lançamento cura o demônio evocado, restaura 1% da mana máxima dele e prolonga |cffffffffAura de Imolação|r em 3 s. Este efeito só pode ocorrer uma vez por segundo."}
T[20353]={"^(.-) Shadowstrike damage every 2 seconds%.%s*$","Causa {{1}} de dano de Golpe Sombrio a cada 2 s."}
T[20799]={"^Releases a bunch of Shadow Bolts%s*$","Libera uma série de Setas Sombrias."}
T[21128]={"^Deals (.-) Shadowstrike damage every 2 seconds%.%s*$","Causa {{1}} de dano de Gelo a cada 2 segundos."}
T[21620]={"^Movement speed increased by (.-)%%%.%s*$","velocidade de movimento aumentada em {{1}}%."}
T[21743]={"^Physical damage taken is increased by (.-)%.%s*$","Dano Físico sofrido aumentou {{1}} p."}
T[23847]={"^Your veins burn as the bloodspore pollen runs through your system!%s*$","Suas veias queimam enquanto o pólen de Esporo Sangrento percorre seu corpo!"}
T[25259]={"^Siphoning (.-) health from nearby allies every (.-) sec%., healing General Vezax%.%s*$","Sugando {{1}} de vida dos aliados próximos a cada {{2}} s, curando ao geral Vezax."}
T[25624]={"^Magical spells cast will cause a delayed backlash%.%s*$","A conjuração mágicos provocará um contragolpe provocardado."}

